function RFULL(){var ya=+$("ra").value,need=ya?[...CSY(ya)]:AR.map((n,i)=>i).filter(i=>OLD.indexOf(AR[i])<0);return need.every(i=>RAS.has(i))}

function CSY(ya){if(!ya)return new Set(AR.map((n,i)=>i));if(ya<NOW.getFullYear()){var c={};ALL.forEach(s=>{if(YF(s[14])===ya)c[s[1]]=(c[s[1]]||0)+1});return new Set(AR.map((n,i)=>i).filter(i=>(c[i]||0)>10))}return new Set(AR.map((n,i)=>i).filter(i=>OLD.indexOf(AR[i])<0))}
function RDEF(){var ya=+$("ra").value;if(!ya){RAS=new Set(AR.map((n,i)=>i));return}if(ya<NOW.getFullYear()){var c={};ALL.forEach(s=>{if(YF(s[14])===ya)c[s[1]]=(c[s[1]]||0)+1});RAS=new Set(AR.map((n,i)=>i).filter(i=>(c[i]||0)>10))}else RAS=new Set(AR.map((n,i)=>i).filter(i=>OLD.indexOf(AR[i])<0))}

